import{_ as e,c as r,o as t,a2 as s}from"./chunks/framework.DdOM6S6U.js";const g=JSON.parse('{"title":"CompleteRegisterController","description":"","frontmatter":{"sidebarPos":2,"sidebarTitle":"CompleteRegisterController"},"headers":[],"relativePath":"system-reference/backend/http/controllers/auth/complete-register-controller.md","filePath":"system-reference/backend/http/controllers/auth/complete-register-controller.md","lastUpdated":1778363927000}'),o={name:"system-reference/backend/http/controllers/auth/complete-register-controller.md"},i=s('<h1 id="completeregistercontroller" tabindex="-1">CompleteRegisterController <a class="header-anchor" href="#completeregistercontroller" aria-label="Permalink to &quot;CompleteRegisterController&quot;">​</a></h1><p><strong>File</strong>: <code>src/Http/Controllers/Auth/CompleteRegisterController.php</code><br><strong>Namespace</strong>: <code>Unusualify\\Modularous\\Http\\Controllers\\Auth</code><br><strong>Extends</strong>: <code>Auth\\Controller</code><br><strong>Traits</strong>: <code>CreateVerifiedEmailAccount</code>, <code>RespondsWithJsonOrRedirect</code></p><p>Second step in the email-verified registration flow. After the user verifies their email via <a href="./pre-register-controller">PreRegisterController</a>, this controller displays the full registration form and creates the user account.</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h2><h3 id="broker" tabindex="-1"><code>broker()</code> <a class="header-anchor" href="#broker" aria-label="Permalink to &quot;`broker()`&quot;">​</a></h3><p>Returns the register broker via <code>Register::broker()</code>.</p><h3 id="showcompleteregisterform-request-request-token-null-view-redirectresponse" tabindex="-1"><code>showCompleteRegisterForm(Request $request, $token = null): View|RedirectResponse</code> <a class="header-anchor" href="#showcompleteregisterform-request-request-token-null-view-redirectresponse" aria-label="Permalink to &quot;`showCompleteRegisterForm(Request $request, $token = null): View|RedirectResponse`&quot;">​</a></h3><p>Displays the complete registration form if the email/token combination is valid.</p><ol><li>Extracts <code>token</code> from the route and <code>email</code> from the query string.</li><li>Validates the token exists for the email via <code>Register::broker(&#39;register_verified_users&#39;)-&gt;emailTokenExists()</code>.</li><li>Fires the <code>ModularousUserRegistering</code> event.</li><li>Builds the form schema from <code>getFormDraft(&#39;complete_register_form&#39;)</code>, pre-filling fields from the request (excluding password fields).</li><li>Renders the registration view.</li></ol><p>If the token is invalid or expired, redirects to the email form with an error.</p><h3 id="completeregister-request-request-jsonresponse-redirectresponse" tabindex="-1"><code>completeRegister(Request $request): JsonResponse|RedirectResponse</code> <a class="header-anchor" href="#completeregister-request-request-jsonresponse-redirectresponse" aria-label="Permalink to &quot;`completeRegister(Request $request): JsonResponse|RedirectResponse`&quot;">​</a></h3><p>Processes the registration form submission:</p><ol><li>Validates all fields via the <code>CreateVerifiedEmailAccount</code> rules.</li><li>Calls <code>broker()-&gt;register()</code> with the submitted credentials.</li><li>On success, calls <code>registerEmail()</code> which: <ul><li>Creates the <code>User</code> record with hashed password and verified email.</li><li>Creates a <code>Company</code> record.</li><li>Assigns the <code>client-manager</code> role.</li><li>Fires <code>ModularousUserRegistered</code> and <code>VerifiedEmailRegister</code> events.</li><li>Logs the user in automatically.</li></ul></li><li>Returns a success or failure response.</li></ol><h3 id="sendregisterresponse-request-request-response-jsonresponse-redirectresponse" tabindex="-1"><code>sendRegisterResponse(Request $request, $response): JsonResponse|RedirectResponse</code> <a class="header-anchor" href="#sendregisterresponse-request-request-response-jsonresponse-redirectresponse" aria-label="Permalink to &quot;`sendRegisterResponse(Request $request, $response): JsonResponse|RedirectResponse`&quot;">​</a></h3><p>Returns a success response with translated message and redirect path.</p><h3 id="sendregisterfailedresponse-request-request-response-jsonresponse-redirectresponse" tabindex="-1"><code>sendRegisterFailedResponse(Request $request, $response): JsonResponse|RedirectResponse</code> <a class="header-anchor" href="#sendregisterfailedresponse-request-request-response-jsonresponse-redirectresponse" aria-label="Permalink to &quot;`sendRegisterFailedResponse(Request $request, $response): JsonResponse|RedirectResponse`&quot;">​</a></h3><p>Returns a failure response with the error message under the <code>email</code> key.</p><h2 id="validation-rules" tabindex="-1">Validation Rules <a class="header-anchor" href="#validation-rules" aria-label="Permalink to &quot;Validation Rules&quot;">​</a></h2><table><thead><tr><th>Field</th><th>Rules</th></tr></thead><tbody><tr><td><code>token</code></td><td>required</td></tr><tr><td><code>email</code></td><td>required, email</td></tr><tr><td><code>name</code></td><td>required, no consecutive spaces</td></tr><tr><td><code>surname</code></td><td>required, no consecutive spaces</td></tr><tr><td><code>company</code></td><td>required</td></tr><tr><td><code>password</code></td><td>required, confirmed</td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./pre-register-controller">PreRegisterController</a> — first step: sends the email verification link</li><li><a href="./register-controller">RegisterController</a> — direct registration (when email verification is disabled)</li></ul>',21),a=[i];function l(d,n,c,p,h,u){return t(),r("div",null,a)}const R=e(o,[["render",l]]);export{g as __pageData,R as default};
